package me.matsumo.fanbox.core.logs.category

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

// This class is automatically generated by generate-log-classes.
sealed interface AdsLog : LogCategory {

    class InterstitialShowAttempted internal constructor(result: String, isRetry: Boolean) : AdsLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "ads")
            put("event_name", "interstitial_show_attempted")
            put("result", result)
            put("is_retry", isRetry)
        }
    }

    companion object {
        // 投稿詳細を閉じたときに、インタースティシャル広告の表示条件を満たし、表示を試みたときのログ。試みるたびに 1 回送る。表示できたときは、表示が始まった時点で送る
        fun interstitialShowAttempted(result: String, isRetry: Boolean) = InterstitialShowAttempted(result, isRetry)
    }
}
